<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Task Management | AppTasker</title><style>body{margin:0;background:#f5f7fb;font-family:Inter,system-ui;color:#182230}.w{max-width:1100px;margin:auto;padding:24px 16px}.back{color:#526df5;text-decoration:none;font-weight:800}.card{background:#fff;border:1px solid #e7eaf0;border-radius:18px;padding:20px;margin:16px 0}.form{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:10px}.input{padding:12px;border:1px solid #d7dce5;border-radius:10px}.wide{grid-column:1/-1}.btn{border:0;border-radius:10px;padding:11px 14px;background:#526df5;color:#fff;font-weight:800}.row{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:12px;align-items:center;padding:14px 0;border-bottom:1px solid #eee}.muted{color:#667085;font-size:12px}.msg{background:#ecfdf3;color:#087a48;padding:12px;border-radius:10px}@media(max-width:650px){.form,.row{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><main class="w"><a class="back" href="{{ route('admin.dashboard') }}">← Dashboard</a><h1>Task Management</h1>@if(session('success'))<p class="msg">{{ session('success') }}</p>@endif<section class="card"><h2>Create task</h2><form class="form" method="POST" action="{{ route('admin.tasks.store') }}">@csrf<input class="input" name="title" placeholder="Task title" required><select class="input" name="type"><option value="image_resize">Image Resize</option><option value="video_resize">Video Resize</option><option value="image_convert">Image Convert</option></select><input class="input" type="number" step="0.01" min="0" name="reward" placeholder="Reward" required><select class="input" name="slot"><option>morning</option><option>afternoon</option><option>evening</option></select><textarea class="input wide" name="description" placeholder="Task description"></textarea><input type="hidden" name="status" value="available"><button class="btn wide">Create Task</button></form></section><section class="card"><h2>All tasks</h2>@foreach($tasks as $task)<div class="row"><div><strong>{{ $task->title }}</strong><div class="muted">{{ strtoupper($task->type) }}</div></div><strong>${{ number_format((float)$task->reward,2) }}</strong><span>{{ ucfirst($task->status) }}</span><form method="POST" action="{{ route('admin.tasks.status',$task) }}">@csrf @method('PATCH')<button class="btn">{{ $task->status==='available'?'Pause':'Activate' }}</button></form></div>@endforeach</section>{{ $tasks->links() }}</main></body></html>